import assert from 'node:assert/strict';import {pathToFileURL} from 'node:url';import vm from 'node:vm';
const api=(await import(pathToFileURL(process.argv[2]).href)).instantiateMithrilNative({});
let count=0;const pass=()=>count++;
let target;function Ctor(value){target=new.target;this.value=value;}const arg={};const result=api.construct(Ctor,arg);assert.equal(result.value,arg);assert.equal(Object.getPrototypeOf(result),Ctor.prototype);assert.equal(target,Ctor);pass();
class Class{constructor(v){this.value=v;}}assert.equal(api.construct(Class,arg).value,arg);pass();
const replacement={};function Returns(){return replacement;}assert.equal(api.construct(Returns,arg),replacement);for(const c of [null,undefined,0,{},()=>{}])assert.throws(()=>api.construct(c,arg),TypeError);pass();
const boom={};function Throws(){throw boom;}assert.throws(()=>api.construct(Throws,arg),e=>e===boom);pass();
let events=[];assert.equal(api.constructOrder(()=>{events.push('ctor');return Ctor},()=>{events.push('arg');return arg}).value,arg);assert.deepEqual(events,['ctor','arg']);pass();
events=[];assert.throws(()=>api.constructOrder(()=>{events.push('ctor');throw boom},()=>{events.push('arg')}),e=>e===boom);assert.deepEqual(events,['ctor']);pass();
const proxy=new Proxy(Ctor,{construct(t,args,newTarget){assert.equal(newTarget,proxy);assert.deepEqual(args,[arg]);return replacement;}});assert.equal(api.construct(proxy,arg),replacement);pass();
const Foreign=vm.runInNewContext('(class { constructor(v){this.value=v;} })');const foreign=api.construct(Foreign,arg);assert.equal(Object.getPrototypeOf(foreign),Foreign.prototype);assert.equal(foreign.value,arg);pass();
assert.deepEqual(api.spread([1,,3],arg),[1,undefined,3,arg,1,undefined,3]);assert.deepEqual(api.spread('ab',arg),['a','b',arg,'a','b']);pass();
let iterations=0;const iterable={*[Symbol.iterator](){iterations++;yield iterations;yield arg;}};assert.deepEqual(api.spread(iterable,0),[1,arg,0,2,arg]);assert.equal(iterations,2);pass();
for(const v of [null,undefined,{},1])assert.throws(()=>api.spread(v,0),TypeError);pass();
let valueReads=0,returned=0;const abrupt={[Symbol.iterator](){return {next(){return {done:false,get value(){valueReads++;throw boom}}},return(){returned++;return {done:true}}}}};assert.throws(()=>api.spread(abrupt,0),e=>e===boom);assert.equal(valueReads,1);assert.equal(returned,0);pass();
for(const o of [null,undefined]){events=[];assert.equal(api.optional(()=>{events.push('object');return o},()=>{events.push('key');return 'f'},()=>{events.push('arg');return arg}),undefined);assert.deepEqual(events,['object']);}pass();
events=[];const receiver={get f(){events.push('lookup');return function(v){events.push('call');assert.equal(this,receiver);assert.equal(arguments.length,1);return v}}};assert.equal(api.optional(()=>{events.push('object');return receiver},()=>{events.push('key');return { [Symbol.toPrimitive](){events.push('coerce');return 'f'}}},()=>{events.push('arg');return arg}),arg);assert.deepEqual(events,['object','key','coerce','lookup','arg','call']);pass();
events=[];assert.throws(()=>api.optional(()=>({}),()=>{events.push('key');return 'f'},()=>{events.push('arg');return arg}),TypeError);assert.deepEqual(events,['key','arg']);pass();
events=[];assert.throws(()=>api.optional(()=>({get f(){throw boom}}),()=> 'f',()=>{events.push('arg')}),e=>e===boom);assert.deepEqual(events,[]);pass();
const rev=Proxy.revocable({},{});rev.revoke();assert.throws(()=>api.optional(()=>rev.proxy,()=> 'f',()=>arg),TypeError);pass();
const values=[null,undefined,0,-0,1,-1,NaN,Infinity,'0','x',0n,1n,{},false];for(const a of values)for(const b of values)assert.equal(api.greater(a,b),a>=b);pass();
events=[];const left={[Symbol.toPrimitive](hint){events.push('left:'+hint);return 2}},right={[Symbol.toPrimitive](hint){events.push('right:'+hint);return 1}};assert.equal(api.greater(left,right),true);assert.deepEqual(events,['left:number','right:number']);pass();
assert.throws(()=>api.greater(Symbol('x'),1),TypeError);assert.throws(()=>api.greater({[Symbol.toPrimitive](){throw boom}},1),e=>e===boom);pass();
assert.equal(count,20);console.log('Native array primitives: 20 runtime contract groups passed.');
